import React, { useEffect, useState } from "react";
import axios from "axios";

function Dashboard() {
  const [buyers, setBuyers] = useState([]);

  useEffect(() => {
    axios.get("http://localhost:8000/buyers")
      .then((response) => {
        setBuyers(response.data);
      })
      .catch((error) => {
        console.error(error);
      });
  }, []);

  return (
    <div style={{ padding: "20px", fontFamily: "Arial" }}>
      <h1>Buyer Risk Dashboard</h1>

      <table border="1" cellPadding="10">
        <thead>
          <tr>
            <th>Buyer ID</th>
            <th>Name</th>
            <th>Risk Score</th>
            <th>Risk Level</th>
          </tr>
        </thead>
        <tbody>
          {buyers.map((buyer) => (
            <tr key={buyer.id}>
              <td>{buyer.id}</td>
              <td>{buyer.name}</td>
              <td>{buyer.risk_score}</td>
              <td>{buyer.risk_level}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default Dashboard;
